    state.records=sample.map(x=>({...x,entity:'餐服项目部'})).concat(hist).sort((a,b)=>String(a.period).localeCompare(String(b.period)));
    state.source=hist.length?'餐服项目数据（经营利润+工资）.xlsx · 26年1到6月经营利润 + 扩展数据集补齐 2024/2025 餐服逐月':'餐服项目数据（经营利润+工资）.xlsx · 26年1到6月经营利润';
    state.isSample=true;state.pending=null;
    state.importInfo=recordsImportInfo(state.records);
    state.biMonth='2026-06';state.biFrom='';state.stage=0;detect();render();
