  function stageWorkbook(name,book){const sheets=workbookSheets(book);if(!sheets.some(s=>s.rows.length))throw new Error('文件中没有可读取的工作表。');state.pending=makePending(name,sheets);state.stage=0;render();toast('文件已读取，请核对工作表、单位和字段映射')}
  async function upload(file){if(!file)return;try{if(!/\.(xlsx|xlsm|xls|csv|tsv)$/i.test(file.name))throw new Error('请选择 Excel（.xlsx/.xls/.xlsm）、CSV 或 TSV 文件。');const isText=/\.(csv|tsv)$/i.test(file.name);const content=isText?await file.text():await file.arrayBuffer();const book=XLSX.read(content,{type:isText?'string':'array',cellDates:true,cellFormula:true});stageWorkbook(file.name,book)}catch(e){toast(`读取失败：${e.message}`)}}
  function stagePaste(){const text=state.paste.trim();if(!text){toast('先从在线表格复制单元格，再粘贴到文本框');return}try{const book=XLSX.read(text,{type:'string',cellDates:true});stageWorkbook('在线表格粘贴内容',book)}catch(e){toast(`粘贴内容未识别：${e.message}`)}}
  function refreshSuggestion(){const p=state.pending,s=p.sheets[p.index];const g=layoutGuess(s,p.year);if(p.mode==='horizontal'){if(g.mode==='horizontal'){p.header=g.header;p.labelCol=g.labelCol;p.mapping=g.mapping}else{p.header=0;p.labelCol=0;p.mapping=bestMapping(s.rows.map(r=>r[0]))}}else{if(g.mode==='vertical'){p.header=g.header;p.mapping=g.mapping}else{p.header=0;p.mapping=bestMapping(s.rows[0]||[])}}p.unit=autoUnit(s,p);p.preview=previewPending(p)}
