  function previewTable(records,limit=8){const shown=records.slice(0,limit);return `<div class="tablewrap"><table><thead><tr><th>月份</th><th>项目/子公司</th><th class="numcol">营业收入</th><th class="numcol">开票金额</th><th class="numcol">应发工资</th><th class="numcol">扣款</th><th class="numcol">原表净利润</th></tr></thead><tbody>${shown.map(r=>`<tr><td>${escape(r.period)}</td><td>${escape(r.entity||'当前项目')}</td><td class="numcol">${money(r.revenue)}</td><td class="numcol">${money(r.invoice)}</td><td class="numcol">${money(r.wage)}</td><td class="numcol">${money(r.deduction)}</td><td class="numcol ${r.profit<0?'negative':''}">${money(r.profit)}</td></tr>`).join('')}</tbody></table></div>${records.length>limit?`<div class="fieldhint">这里只预览前${limit}行；确认后分析全部${records.length}行。</div>`:''}`}
